import puppeteer from 'puppeteer';
import fs from 'fs/promises';
import path from 'path';

const STATE_ROOT = process.env.STATE_ROOT || './state';
const outputDir = path.join(STATE_ROOT, 'output');

(async () => {
  await fs.mkdir(outputDir, { recursive: true });
  const browser = await puppeteer.launch({ headless: 'new' });
  try {
    const page = await browser.newPage();
    await page.goto('https://example.com', { waitUntil: 'domcontentloaded' });
    const title = await page.title();
    await fs.writeFile(path.join(outputDir, 'title.txt'), title, 'utf-8');
    console.log(`Saved title: "${title}" to ${outputDir}/title.txt`);
  } finally {
    await browser.close();
  }
})();
